excels.excel:

EXPORT WITH SHEET="招标比价定标记录", HEADER=true,
    MAPPING={"a":"投标单位","b":"商务报价","c":"技术得分","d":"业绩得分","e":"综合评分","f":"定标结果"},
    FORMAT={"b":"#,##0.00","c":"#,##0.0","d":"#,##0.0","e":"#,##0.00"},
    FORMULAS={
        E2:'C2*0.7+D2*0.3',E3:'C3*0.7+D3*0.3',E4:'C4*0.7+D4*0.3',
        E5:'C5*0.7+D5*0.3',E6:'C6*0.7+D6*0.3',
        B7:'AVERAGE(B2:B6)',E7:'AVERAGE(E2:E6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        B4:{color:red,bold:true}
    }
